INSERT INTO `actors` VALUES (1,'Tim','Robbins','1958-10-16','USA','Amerykański aktor, scenarzysta, reżyser i producent filmowy. Laureat Oscara dla najlepszego aktora drugoplanowego za rolę w filmie Rzeka tajemnic (2003). Zasłynął przede wszystkim kreacją Andy\'ego Dufresne w legendarnym dramacie Skazani na Shawshank.','https://thumb.wikimedia.org/wikipedia/commons/thumb/6/61/TimRobbins131015_%2810_of_31%29_%28cropped%29.jpg/500px-TimRobbins131015_%2810_of_31%29_%28cropped%29.jpg','2026-11-13 00:45:09'),(2,'Morgan','Freeman','1937-06-01','USA','Jeden z najwybitniejszych i najbardziej szanowanych amerykańskich aktorów filmowych oraz narratorów. Laureat Oscara za rolę w Za wszelką cenę (2004). Znany z niezrównanego głosu i ról m.in. w Skazanych na Shawshank, Siedem oraz trylogii Mrocznego Rycerza.','https://thumb.wikimedia.org/wikipedia/commons/thumb/4/42/Morgan_Freeman_at_The_Pentagon_on_2_August_2023_-_230802-D-PM193-3363_%28cropped%29.jpg/500px-Morgan_Freeman_at_The_Pentagon_on_2_August_2023_-_230802-D-PM193-3363_%28cropped%29.jpg','2026-11-13 00:45:09'),(3,'Marlon','Brando','1924-04-03','USA','Uznawany za jednego z najważniejszych aktorów w dziejach kina. Wprowadził realizm psychologiczny metody Stanisławskiego. Zdobywca dwóch Oscarów za role w Na nabrzeżach oraz jako Don Vito Corleone w Ojcu chrzestnym.','https://thumb.wikimedia.org/wikipedia/commons/thumb/5/53/Marlon_Brando_publicity_for_One-Eyed_Jacks.png/500px-Marlon_Brando_publicity_for_One-Eyed_Jacks.png','2026-11-13 00:45:09'),(4,'Al','Pacino','1940-04-25','USA','Legenda kina i teatru, zdobywca Oscara, potrójnego Złotego Globu i nagród BAFTA. Pamiętny Michael Corleone w Ojcu chrzestnym, Tony Montana w Człowieku z blizną oraz Vincent Hanna w Gorączce.','https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5b/Al_Pacino_2016_%2830401544273%29.jpg/500px-Al_Pacino_2016_%2830401544273%29.jpg','2026-11-13 00:45:09'),(5,'Christian','Bale','1974-01-30','Wielka Brytania','Brytyjski aktor znany z niezwykłego poświęcenia do ról i spektakularnych przemian fizycznych. Laureat Oscara za rolę w The Fighter. Stworzył jedną z najbardziej docenionych kreacji Bruce\'a Wayne\'a w trylogii Mroczny Rycerz Christophera Nolana.','https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0a/Christian_Bale_2022.jpg/500px-Christian_Bale_2022.jpg','2026-11-13 00:45:09'),(6,'Heath','Ledger','1979-04-04','Australia','Wybitny australijski aktor filmowy. Jego rola Jokera w Mrocznym Rycerzu przeszła do historii kina jako jedno z najbardziej hipnotyzujących wcieleń aktorskich, uhonorowana pośmiertnym Oscarem.','https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ea/Heath_Ledger_%28Berlin_Film_Festival_2006%29_crop.jpg/500px-Heath_Ledger_%28Berlin_Film_Festival_2006%29_crop.jpg','2026-11-13 00:45:09'),(7,'John','Travolta','1954-02-18','USA','Amerykański aktor, tancerz i piosenkarz. Ikona popkultury lat 70. (Gorączka sobotniej nocy, Grease), który powrócił w glorii rolą płatnego mordercy Vincenta Vegi w kultowym Pulp Fiction Quentina Tarantino.','https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7d/John_Travolta_at_the_2024_Toronto_International_Film_Festival_%28cropped%29.jpg/500px-John_Travolta_at_the_2024_Toronto_International_Film_Festival_%28cropped%29.jpg','2026-11-13 00:45:09'),(8,'Samuel L.','Jackson','1948-12-21','USA','Jeden z najbardziej kasowych aktorów w historii światowego kina. Wystąpił w ponad 150 filmach. Nominowany do Oscara za charyzmatyczną rolę Julesa Winnfielda w Pulp Fiction.','https://thumb.wikimedia.org/wikipedia/commons/thumb/2/29/SamuelLJackson.jpg/500px-SamuelLJackson.jpg','2026-11-13 00:45:09'),(9,'Elijah','Wood','1981-01-28','USA','Aktor filmowy i dubbingowy, producent. Największą międzynarodową sławę przyniosła mu główna rola hobbita Froda Bagginsa w monumentalnej trylogii filmowej Władca Pierścieni Petera Jacksona.','https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b0/Elijah_Wood_by_Gage_Skidmore_3.jpg/500px-Elijah_Wood_by_Gage_Skidmore_3.jpg','2026-11-13 00:45:09'),(10,'Ian','McKellen','1939-05-25','Wielka Brytania','Wybitny brytyjski aktor teatralny i filmowy, mistrz ról szekspirowskich. Światową popularność zdobył jako czarodziej Gandalf we Władcy Pierścieni i Hobbicie oraz Magneto w serii X-Men.','https://thumb.wikimedia.org/wikipedia/commons/thumb/1/15/SDCC13_-_Ian_McKellen_%289363024840%29.jpg/500px-SDCC13_-_Ian_McKellen_%289363024840%29.jpg','2026-11-13 00:45:09'),(11,'Tom','Hanks','1956-07-09','USA','Dwukrotny laureat Oscara z rzędu (za Filadelfię i Forresta Gumpa). Jeden z najbardziej lubianych i rozpoznawalnych aktorów Hollywood, znany również z ról w Cast Away, Szeregowcu Ryanie i Apollo 13.','https://thumb.wikimedia.org/wikipedia/commons/thumb/3/39/TomHanksPrincEdw031223_%2811_of_41%29_%28cropped%29.jpg/500px-TomHanksPrincEdw031223_%2811_of_41%29_%28cropped%29.jpg','2026-11-13 00:45:09'),(12,'Leonardo','DiCaprio','1974-11-11','USA','Laureat Oscara za film Zjawa, jeden z najbardziej wpływowych aktorów współczesnego kina. Gwiazda takich filmów jak Titanic, Incepcja, Wilk z Wall Street, Aviator czy Wyspa tajemnic.','https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2d/LeoPTABFI191125-28_%28cropped%29.jpg/500px-LeoPTABFI191125-28_%28cropped%29.jpg','2026-11-13 00:45:09'),(13,'Keanu','Reeves','1964-09-02','Kanada','Uwielbiany na całym świecie aktor kina akcji i science-fiction. Nieśmiertelny Neo w przełomowej trylogii Matrix braci Wachowskich oraz tytułowy bezwzględny zabójca w serii John Wick.','https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b4/Keanu_Reeves_at_TIFF_2025_02_%28Cropped%29.jpg/500px-Keanu_Reeves_at_TIFF_2025_02_%28Cropped%29.jpg','2026-11-13 00:45:09'),(14,'Brad','Pitt','1963-12-18','USA','Laureat dwóch Oscarów (jako producent i aktor drugoplanowy). Stworzył ikoniczne kreacje w filmach Podziemny krąg (jako Tyler Durden), Siedem, Bękarty wojny oraz Pewnego razu... w Hollywood.','https://thumb.wikimedia.org/wikipedia/commons/thumb/9/90/Brad_Pitt-69858.jpg/500px-Brad_Pitt-69858.jpg','2026-11-13 00:45:09'),(15,'Edward','Norton','1969-08-18','USA','Trzykrotnie nominowany do Oscara za role w Lęku pierwotnym, Więźniu nienawiści oraz Birdmanie. W filmie Podziemny krąg Davida Finchera zagrał bezimiennego Narratora cierpiącego na bezsenność.','https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b1/Ed_Norton_and_Shauna_Robertson_TIFF_2025_%28cropped%29.jpg/500px-Ed_Norton_and_Shauna_Robertson_TIFF_2025_%28cropped%29.jpg','2026-11-13 00:45:09'),(16,'Matthew','McConaughey','1969-11-04','USA','Laureat Oscara za pierwszoplanową rolę w Witaj w klubie (Dallas Buyers Club). Znakomicie poprowadził widowisko science-fiction Interstellar jako pilot Joseph Cooper oraz serial Detektyw.','https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0d/Matthew_McConaughey_at_the_2025_Toronto_Film_Festival_%283x4_cropped%29.jpg/500px-Matthew_McConaughey_at_the_2025_Toronto_Film_Festival_%283x4_cropped%29.jpg','2026-11-13 00:45:09'),(17,'Jodie','Foster','1962-11-19','USA','Dwukrotna zdobywczyni Oscara dla najlepszej aktorki (Oskarżeni, Milczenie owiec). Jako młoda agentka FBI Clarice Starling stworzyła jedną z najbardziej pamiętnych kobiecych ról w historii kina.','https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ed/Jodie_Foster_Taxi_Driver_Tribeca_Festival_2026-20_%28cropped%29.jpg/500px-Jodie_Foster_Taxi_Driver_Tribeca_Festival_2026-20_%28cropped%29.jpg','2026-11-13 00:45:09'),(18,'Anthony','Hopkins','1937-12-31','Wielka Brytania','Walijski aktor filmowy i teatralny, dwukrotny laureat Oscara. Jego brawurowe, niespełna 16-minutowe wcielenie w postać demonicznego doktora Hannibala Lectera w Milczeniu owiec przyniosło mu statuetkę Akademii.','https://thumb.wikimedia.org/wikipedia/commons/thumb/6/63/Anthony_Hopkins_Red_Sea_Festival_2025_Portrait_%28cropped%29.jpg/500px-Anthony_Hopkins_Red_Sea_Festival_2025_Portrait_%28cropped%29.jpg','2026-11-13 00:45:09'),(19,'Robert','De Niro','1943-08-17','USA','Dwukrotny zdobywca Oscara (za Ojca chrzestnego II oraz Wściekłego Byka). Niezrównany mistrz kina gangsterskiego i wieloletni współpracownik Martina Scorsese (Taksówkarz, Chłopcy z ferajny, Kasyno).','https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c1/Robert_de_Niro_Cannes_Film_Festival_%283x4_cropped%29.jpg/500px-Robert_de_Niro_Cannes_Film_Festival_%283x4_cropped%29.jpg','2026-11-13 00:45:09'),(20,'Ray','Liotta','1954-12-18','USA','Amerykański aktor charakteryzujący się magnetyczną, intensywną grą. Zagrał główną rolę gangstera Henry\'ego Hilla w arcydziele Martina Scorsese Chłopcy z ferajny.','https://thumb.wikimedia.org/wikipedia/commons/thumb/2/23/Ray_Liotta_Deauville_2014_3.jpg/500px-Ray_Liotta_Deauville_2014_3.jpg','2026-11-13 00:45:09'),(21,'Liam','Neeson','1952-06-07','Wielka Brytania','Aktor pochodzący z Irlandii Północnej, nominowany do Oscara za tytułową rolę w dramacie wojennym Lista Schindlera Stevena Spielberga. Znany także z serii Uprowadzona i roli Qui-Gona Jinna w Gwiezdnych wojnach.','https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fe/Liam_Neeson_Deauville_2012_2.jpg/500px-Liam_Neeson_Deauville_2012_2.jpg','2026-11-13 00:45:09'),(22,'Russell','Crowe','1964-04-07','Nowa Zelandia','Laureat Oscara dla najlepszego aktora za rolę rzymskiego generała Maximusa w epickim Gladiatorze Ridleya Scotta. Gwiazda filmów Piękny umysł, Informator i Pan i władca: Na krańcu świata.','https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fa/Russell_Crowe_Venice_2026.jpg/500px-Russell_Crowe_Venice_2026.jpg','2026-11-13 00:45:09'),(23,'Joaquin','Phoenix','1974-10-28','USA','Jeden z najwybitniejszych aktorów swojego pokolenia, zdobywca Oscara za tytułową rolę w Jokerze. W filmie Gladiator stworzył wybitną postać bezwzględnego i zepsutego cesarza Kommodusa.','https://thumb.wikimedia.org/wikipedia/commons/thumb/d/dc/Joaquin_Phoenix-64908_%28cropped%29.jpg/500px-Joaquin_Phoenix-64908_%28cropped%29.jpg','2026-11-13 00:45:09'),(24,'Kate','Winslet','1975-10-05','Wielka Brytania','Jedna z najbardziej utalentowanych aktorek współczesnego kina, zdobywczyni Oscara za Lektora. Światowy rozgłos i uwielbienie widzów zyskała rolą arystokratki Rose DeWitt Bukater w megahicie Titanic.','https://thumb.wikimedia.org/wikipedia/commons/thumb/5/53/KateWinslet_%28cropped%29.jpg/500px-KateWinslet_%28cropped%29.jpg','2026-11-13 00:45:09'),(25,'Song','Kang-ho','1967-01-17','Korea Południowa','Czołowy aktor kina południowokoreańskiego, zdobywca Złotej Palmy w Cannes. Międzynarodowe uznanie zdobył główną rolą głowy ubogiej rodziny Ki-taeka w nagrodzonym czterema Oscarami filmie Parasite.','https://upload.wikimedia.org/wikipedia/commons/d/df/Song_Gangho_2016.jpg','2026-11-13 00:45:09'),(26,'Miles','Teller','1987-02-20','USA','Amerykański aktor młodego pokolenia. Wcielił się w postać ambitnego, obsesyjnego młodego perkusisty jazzowego Andrew Neimana w obsypanym nagrodami dramacie Whiplash.','https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c8/Miles_Teller_TIFF_2025_%283x4_cropped%29.png/500px-Miles_Teller_TIFF_2025_%283x4_cropped%29.png','2026-11-13 00:45:09'),(27,'J. K.','Simmons','1955-01-09','USA','Wybitny amerykański aktor charakterystyczny, nagrodzony Oscarem za bezwzględną, terroryzującą postać dyrygenta Terence\'a Fletchera w filmie Whiplash.','https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5b/JK_Simmons_at_the_2024_Toronto_International_Film_Festival_%28cropped%29.jpg/500px-JK_Simmons_at_the_2024_Toronto_International_Film_Festival_%28cropped%29.jpg','2026-11-13 00:45:09'),(28,'Jean','Reno','1948-07-30','Francja','Francuski aktor hiszpańskiego pochodzenia, ulubieniec Luca Bessona. Międzynarodową sławę przyniósł mu poruszający występ jako małomówny płatny zabójca z zasadami w filmie Leon zawodowiec.','https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e3/Jean_Reno_Cannes_2016.jpg/500px-Jean_Reno_Cannes_2016.jpg','2026-11-13 00:45:09'),(29,'Natalie','Portman','1981-06-09','USA','Laureatka Oscara za Czarny łabędź. Zadebiutowała na wielkim ekranie w wieku 12 lat genialną i odważną kreacją osieroconej Mathildy w kultowym filmie Leon zawodowiec.','https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f9/NataliePortman.jpg/500px-NataliePortman.jpg','2026-11-13 00:45:09');
