INSERT INTO `movies` VALUES (1,'Skazani na Shawshank',1994,'Frank Darabont',142,'Młody bankier Andy Dufresne zostaje niesłusznie skazany na podwójne dożywocie za zamordowanie żony i jej kochanka. Trafia do ponurego więzienia Shawshank o zaostrzonym rygorze, gdzie rządzi bezwzględny naczelnik Norton i brutalni strażnicy. Dzięki niezwykłej inteligencji, cierpliwości i przyjaźni z czarnoskórym przemytnikiem Redem, Andy odnajduje sposób, by zachować godność i nadzieję w nieludzkim świecie.','https://image.tmdb.org/t/p/w500/9cqNxx0GxF0bflZmeSMuL5tnGzr.jpg','2026-11-13 00:45:09'),(2,'Ojciec chrzestny',1972,'Francis Ford Coppola',175,'Nowy Jork, lata 40. XX wieku. Don Vito Corleone stoi na czele potężnej mafijnej rodziny, która kontroluje związki zawodowe, hazard i polityków. Gdy patriarcha odmawia wejścia w handel narkotykami, dochodzi do zamachu na jego życie. Młodszy syn, wojenny bohater Michael, dotąd trzymający się z dala od nielegalnych interesów familii, zostaje wciągnięty w spiralę przemocy i ostatecznie przejmuje bezwzględną władzę.','https://image.tmdb.org/t/p/w500/3bhkrj58Vtu7enYsRolD1fZdja1.jpg','2026-11-13 00:45:09'),(3,'Mroczny Rycerz',2008,'Christopher Nolan',152,'Batman, wspierany przez porucznika Jima Gordona oraz nowego, nieprzekupnego prokuratora okręgowego Harveya Denta, skutecznie rozbija zorganizowaną przestępczość w Gotham City. Porządek zostaje jednak zburzony, gdy w mieście pojawia się tajemniczy, psychopatyczny anarchista zwany Jokerem. Jego jedynym celem jest pogrążenie społeczeństwa w chaosie i zmuszenie Mrocznego Rycerza do przekroczenia własnych moralnych granic.','https://image.tmdb.org/t/p/w500/qJ2tW6WMUDux911r6m7haRef0WH.jpg','2026-11-13 00:45:09'),(4,'Pulp Fiction',1994,'Quentin Tarantino',154,'Wirtuozerski, nieliniowy kryminał łączący kilka przeplatających się historii ze świata przestępczego Los Angeles. Dwaj płatni mordercy, Vincent Vega i Jules Winnfield, mają odzyskać tajemniczą walizkę swojego bossa Marsellusa Wallace\'a. W międzyczasie Vincent ma za zadanie zaopiekować się kapryśną żoną szefa, Mią, a podstarzały bokser Butch decyduje się oszukać mafię i wygrać ustawioną walkę.','https://image.tmdb.org/t/p/w500/d5iIlFn5s0ImszYzBPb8JPIfbXD.jpg','2026-11-13 00:45:09'),(5,'Władca Pierścieni: Drużyna Pierścienia',2001,'Peter Jackson',178,'W cichym Shire niepozorny hobbit Frodo Baggins dziedziczy potężny Jedyny Pierścień, stworzony przez Czarnego Władcę Saurona, by zniewolić całe Śródziemie. Za namową mądrego czarodzieja Gandalfa, Frodo wraz z przyjaciółmi wyrusza w pełną śmiertelnych niebezpieczeństw wędrówkę ku Górze Przeznaczenia w sercu Mordoru, gdzie oręż zła może zostać zniszczony. Powstaje Drużyna Pierścienia reprezentująca wszystkie wolne ludy.','https://image.tmdb.org/t/p/w500/6oom5QYQ2yQTMJIbnvbkBL9cHo6.jpg','2026-11-13 00:45:09'),(6,'Forrest Gump',1994,'Robert Zemeckis',142,'Wzruszająca opowieść o życiu prostodusznego mężczyzny z Alabamy o niskim ilorazie inteligencji, lecz ogromnym sercu. Forrest przypadkowo staje się uczestnikiem najważniejszych wydarzeń powojennej Ameryki: od wojny w Wietnamie, przez ruch hippisowski, aferę Watergate, aż po narodziny potęgi Apple. Mimo sławy i fortuny, przez całe życie pozostaje wierny swojej jedynej miłości z dzieciństwa — zbuntowanej Jenny.','https://image.tmdb.org/t/p/w500/arw2vcBveWOVZr6pxd9XTd1TdQa.jpg','2026-11-13 00:45:09'),(7,'Incepcja',2010,'Christopher Nolan',148,'Dom Cobb jest mistrzem ekstrakcji — wykradania najcenniejszych sekretów z ludzkiej podświadomości podczas snu, gdy umysł jest najbardziej bezbronny. Przez swoją niebezpieczną profesję Cobb stał się międzynarodowym uciekinierem, który stracił wszystko, co kochał. Otrzymuje szansę na odkupienie i powrót do dzieci, ale musi dokonać rzeczy uchodzącej za niemożliwą: incepcji, czyli zaszczepienia obcej myśli w głowie dziedzica potężnego imperium.','https://image.tmdb.org/t/p/w500/oYuLEt3zVCKq57qu2F8dT7NIa6f.jpg','2026-11-13 00:45:09'),(8,'Matrix',1999,'Lana Wachowski, Lilly Wachowski',136,'Thomas Anderson wiedzie podwójne życie: za dnia jest cichym programistą korporacyjnym, w nocy zaś genialnym hakerem działającym pod pseudonimem Neo. Pewnego dnia kontaktuje się z nim legendarny Morfeusz, który uświadamia mu przerażającą prawdę: znany ludziom świat to jedynie cyfrowa symulacja stworzona przez maszyny, a ludzkość służy im jako źródło bioelektrycznej energii. Neo staje się Wybrańcem walczącym o wyzwolenie rasy ludzkiej.','https://image.tmdb.org/t/p/w500/f89U3ADr1oiB1s9GkdPOEpXUk5H.jpg','2026-11-13 00:45:09'),(9,'Podziemny krąg',1999,'David Fincher',139,'Wyczerpany życiem, cierpiący na chroniczną bezsenność bezimienny urzędnik korporacji próbuje odnaleźć sens w konsumpcyjnym świecie. Podczas podróży służbowej poznaje ekscentrycznego sprzedawcę mydła, Tylera Durdena, który głosi wyzwolenie z sideł cywilizacji poprzez fizyczną walkę. Razem zakładają sekretny Podziemny Krąg, w którym sfrustrowani mężczyźni biją się na gołe pięści. Organizacja szybko wymyka się spod kontroli.','https://image.tmdb.org/t/p/w500/pB8BM7pdSp6B6Ih7QZ4DrQ3PmJK.jpg','2026-11-13 00:45:09'),(10,'Interstellar',2014,'Christopher Nolan',169,'W niedalekiej przyszłości Ziemia ulega postępującej katastrofie ekologicznej, a ludzkości grozi wymarcie z powodu głodu i plag niszczących uprawy. Grupa naukowców z tajnej bazy NASA odkrywa w pobliżu Saturna tunel czasoprzestrzenny. Były pilot testowy Joseph Cooper zostaje zmuszony do opuszczenia ukochanych dzieci i wyruszenia na czele międzygwiezdnej misji badawczej, by znaleźć nowy dom dla człowieka poza naszą galaktyką.','https://image.tmdb.org/t/p/w500/gEU2QniE6E77NI6lCU6MxlNBvIx.jpg','2026-11-13 00:45:09'),(11,'Milczenie owiec',1991,'Jonathan Demme',118,'Młoda, ambitna kursantka akademii FBI Clarice Starling zostaje wyznaczona do przeprowadzenia wywiadu z uwięzionym w szpitalu psychiatrycznym psychiatrą i kanibalem, dr. Hannibalem Lecterem. FBI liczy, że przenikliwy geniusz uwięzionego potwora pomoże schwytać seryjnego zabójcę kobiet zwanego Buffalo Billem. Między inteligentną agentką a demonicznym więźniem rodzi się niebezpieczna psychologiczna gra.','https://image.tmdb.org/t/p/w500/uS9m8OBk1A8eM9I042bx8XXpqAq.jpg','2026-11-13 00:45:09'),(12,'Siedem',1995,'David Fincher',127,'Doświadczony, zgorzkniały detektyw Somerset, stojący na progu emerytury, oraz młody, impulsywny detektyw Mills stają w obliczu serii makabrycznych zbrodni w mrocznym, bezimiennym mieście. Bezwzględny, religijnie zmotywowany morderca wybiera swoje ofiary i aranżuje miejsca kaźni zgodnie z biblijnym katalogiem siedmiu grzechów głównych: obżarstwa, chciwości, lenistwa, nieczystości, pychy, zazdrości i gniewu.','https://image.tmdb.org/t/p/w500/6yoghtyTpznpBik8EngEmJskVUO.jpg','2026-11-13 00:45:09'),(13,'Chłopcy z ferajny',1990,'Martin Scorsese',145,'Oparta na faktach historia Henry\'ego Hilla, pół-Irlandczyka, pół-Włocha, który od najmłodszych lat marzył tylko o jednym: by stać się gangsterem. Wkracza w szeregi nowojorskiej mafii pod skrzydła doświadczonego Jimmy\'ego Conwaya i nieobliczalnego Tommy\'ego DeVito. Po dekadach pełnych luksusu, napadów i bezwzględnych porachunków, pętla narkotykowa i strach przed dawnymi przyjaciółmi zmuszają go do zdrady.','https://image.tmdb.org/t/p/w500/aKuFiU82s5ISJpGZp7YkIr3kCUd.jpg','2026-11-13 00:45:09'),(14,'Lista Schindlera',1993,'Steven Spielberg',195,'Kraków, czas II wojny światowej. Niemiecki przedsiębiorca Oskar Schindler przybywa do okupowanej Polski, by dorobić się fortuny na taniej sile roboczej w fabryce naczyń emaliowanych. Będąc świadkiem bestialstwa nazistów i likwidacji krakowskiego getta, Schindler przechodzi głęboką przemianę wewnętrzną. Ryzykując majątek i własne życie, z pomocą księgowego Itzhaka Sterna wykupuje ponad 1100 żydowskich robotników, ratując ich przed śmiercią.','https://image.tmdb.org/t/p/w500/sF1U4EUQS8YHUYjNl3pMGNIQyr0.jpg','2026-11-13 00:45:09'),(15,'Gladiator',2000,'Ridley Scott',155,'Generał rzymskich legionów Maximus Decimus Meridius prowadzi wojska ku ostatecznemu zwycięstwu nad germańskimi plemionami. Umierający cesarz Marek Aureliusz pragnie przekazać mu rządy nad Rzymem. Zazdrosny syn cesarza, Kommodus, morduje ojca, skazuje Maximusa na śmierć, a jego żonę i syna każe zgładzić. Maximus ucieka z rąk oprawców, trafia do niewoli i jako niezwyciężony gladiator powraca do rzymskiego Koloseum, by pomścić rodzinę.','https://image.tmdb.org/t/p/w500/ty8TGRuvJLPUmAR1H1nRIsgwvim.jpg','2026-11-13 00:45:09'),(16,'Titanic',1997,'James Cameron',194,'Kwiecień 1912 roku. Największy, najnowocześniejszy i uchodzący za niezatapialny transatlantyk RMS Titanic wyrusza w swój dziewiczy rejs z Southampton do Nowego Jorku. Na pokładzie spotykają się dwoje młodych ludzi z zupełnie różnych światów: zbuntowana arystokratka Rose oraz ubogi, podróżujący trzecią klasą rysownik Jack Dawson. Mimo konwenansów rodzi się między nimi namiętne uczucie, które zostaje wystawione na próbę w obliczu zderzenia statku z górą lodową.','https://image.tmdb.org/t/p/w500/9xjZS2rlVxm8SFx8kPC3aIGCOYQ.jpg','2026-11-13 00:45:09'),(17,'Parasite',2019,'Bong Joon-ho',132,'Czteroosobowa rodzina Kimów żyje w nędzy w zagrzybionej suterenie w Seulu, ledwo wiążąc koniec z końcem dzięki dorywczym pracom. Los uśmiecha się do nich, gdy syn Ki-woo zdobywa posadę korepetytora języka angielskiego w luksusowej rezydencji bogatej rodziny Parków. Za pomocą sprytnych intryg i fałszywych referencji, kolejni członkowie rodziny bezlitośnie infiltrują dom milionerów, nie spodziewając się ponurej tajemnicy kryjącej się w piwnicy.','https://image.tmdb.org/t/p/w500/7IiTTgloJzvGI1TAYymCfbfl3vT.jpg','2026-11-13 00:45:09'),(18,'Spirited Away: W krainie bogów',2001,'Hayao Miyazaki',125,'Podczas przeprowadzki do nowego domu 10-letnia Chihiro wraz z rodzicami gubi drogę i trafia do tajemniczego, opuszczonego wesołego miasteczka. Gdy rodzice bez opamiętania zjadają jedzenie przeznaczone dla bogów i zostają zamienieni w świnie, Chihiro odkrywa, że znalazła się w świecie duchów, bóstw i magii, rządzonym przez chciwą wiedźmę Yubabę. By uratować rodziców, dziewczynka podejmuje pracę w łaźni dla duchów i uczy się odwagi oraz miłości.','https://image.tmdb.org/t/p/w500/39wmItIWsg5sZMyRUHLkWBcuVCM.jpg','2026-11-13 00:45:09'),(19,'Whiplash',2014,'Damien Chazelle',107,'Dziewiętnastoletni Andrew Neiman jest ambitnym perkusistą jazzowym w najbardziej prestiżowym konserwatorium muzycznym w Nowym Jorku. Marzy o osiągnięciu wielkości na miarę Buddy\'ego Richa. Zostaje zauważony przez Terence\'a Fletchera — bezwzględnego, demonicznego dyrygenta szkolnego zespołu, który stosuje metody terroru psychicznego i przemocy, wierząc, że tylko ekstremalne cierpienie może wykrzesać z człowieka geniusz.','https://image.tmdb.org/t/p/w500/7fn624j5lj3xTme2SgiLCeuedmO.jpg','2026-11-13 00:45:09'),(20,'Leon zawodowiec',1994,'Luc Besson',110,'Leon jest profesjonalnym, samotnym i niemal niewidzialnym płatnym zabójcą żyjącym w nowojorskiej Małej Italii. Jego jedynym przyjacielem jest roślina doniczkowa. Jego monotonne, ascetyczne życie zmienia się gwałtownie, gdy rodzina z sąsiedztwa zostaje zmasakrowana przez skorumpowanych agentów wydziału antynarkotykowego pod wodzą psychopatycznego Stansfielda. Leon ratuje 12-letnią Mathildę, która pragnie zemsty i prosi go o naukę fachu sprzątacza.','https://image.tmdb.org/t/p/w500/fj0hwDJEOOHllRim2BMt5L7tbjf.jpg','2026-11-13 00:45:09');
INSERT INTO `reviews` VALUES (1,1,2,5,'Nie bez powodu ten film od lat okupuje 1. miejsce we wszystkich rankingach wszech czasów. Poruszająca historia nadziei, niezłomności i męskiej przyjaźni w murach Shawshank. Genialny duet Robbinsa i Freemana.','2026-11-13 00:45:09','2026-11-13 00:45:09'),(2,1,3,5,'Wzruszające, piękne kino. Finał na plaży w Zihuatanejo za każdym razem wywołuje łzy wzruszenia. Absolutne 5/5!','2026-11-13 00:45:09','2026-11-13 00:45:09'),(3,2,2,5,'Marlon Brando i Al Pacino stworzyli role życia. Opowieść o władzy, rodzinie i upadku moralnym, która do dziś pozostaje niedoścignionym wzorem dramatu gangsterskiego.','2026-11-13 00:45:09','2026-11-13 00:45:09'),(4,3,2,5,'Heath Ledger jako Joker wzbił się na wyżyny aktorstwa. To nie jest po prostu komiksowa adaptacja — to wybitny thriller psychologiczny z genialną muzyką Zimmera.','2026-11-13 00:45:09','2026-11-13 00:45:09'),(5,3,4,5,'Najlepszy film o Batmanie i jeden z najlepszych filmów akcji w historii kina. Mroczny, realistyczny i trzymający w napięciu do ostatniej sekundy.','2026-11-13 00:45:09','2026-11-13 00:45:09'),(6,4,3,5,'Dialogi Tarantino to czysta poezja. Nieliniowa fabuła, taniec Travolty i Umy Thurman, monolog Julesa z Księgi Ezechiela — klasyk, który się nie starzeje.','2026-11-13 00:45:09','2026-11-13 00:45:09'),(7,5,2,5,'Arcydzieło kina fantasy. Muzyka Howarda Shore\'a i pejzaże Nowej Zelandii budują klimat, którego nikt dotąd nie pobił. Prawdziwa kinowa magia.','2026-11-13 00:45:09','2026-11-13 00:45:09'),(8,6,4,5,'Tom Hanks w szczytowej formie. Film bawi, wzrusza i uczy empatii. Oglądałem chyba z dziesięć razy i wciąż chętnie do niego wracam.','2026-11-13 00:45:09','2026-11-13 00:45:09'),(9,7,2,5,'Nolan w szczytowej formie. Koncepcja snu w śnie, genialne efekty praktyczne i zakończenie z wirującym bączkiem, o którym dyskutuje się do dziś.','2026-11-13 00:45:09','2026-11-13 00:45:09'),(10,8,3,5,'Film, który zdefiniował przełom wieków. Cyberpunkowy klimat, zielonkawa paleta barw, filozoficzne pytania i rewolucyjny bullet-time. Kamień milowy kina.','2026-11-13 00:45:09','2026-11-13 00:45:09'),(11,9,4,5,'Pierwsza zasada Fight Clubu: nie rozmawiamy o Fight Clubie! Fenomenalna satyra na konsumpcjonizm i zaskakujący twist fabularny.','2026-11-13 00:45:09','2026-11-13 00:45:09'),(12,10,2,5,'Wizualny i dźwiękowy majstersztyk. Scena na planecie fal oraz motyw upływającego czasu chwytają za gardło. Hans Zimmer stworzył tu jedną ze swoich najlepszych ścieżek.','2026-11-13 00:45:09','2026-11-13 00:45:09'),(13,11,3,5,'Anthony Hopkins spędza na ekranie kilkanaście minut, a hipnotyzuje w każdej sekundzie. Kapitalna gra psychologiczna między Lecterem a agentką Starling.','2026-11-13 00:45:09','2026-11-13 00:45:09'),(14,12,2,5,'Duszny, deszczowy klimat i przerażający finał na pustyni z pudełkiem. Fincher stworzył jeden z najmroczniejszych kryminałów wszech czasów.','2026-11-13 00:45:09','2026-11-13 00:45:09'),(15,13,4,5,'Najlepszy film gangsterski Martina Scorsese. Szybkie tempo, świetna narracja z offu i niezapomniany Joe Pesci (\"Funny how?\").','2026-11-13 00:45:09','2026-11-13 00:45:09'),(16,14,2,5,'Bolesny, wstrząsający i niesamowicie ważny film. Scena z dziewczynką w czerwonym płaszczyku zapada w pamięć na całe życie.','2026-11-13 00:45:09','2026-11-13 00:45:09'),(17,15,3,5,'Epickie widowisko ze wspaniałą rolą Russella Crowe i bezwzględnym Phoenixem. \"Siła i honor!\"','2026-11-13 00:45:09','2026-11-13 00:45:09'),(18,16,4,5,'Cameron stworzył monumentalne widowisko łączące wielki romans z katastroficznym rozmachem. Odtworzenie statku i sceny tonięcia to techniczny geniusz.','2026-11-13 00:45:09','2026-11-13 00:45:09'),(19,17,2,5,'Zasłużone 4 Oscary! Genialny miks czarnej komedii, thrillera i bezlitosnego komentarza społecznego o podziałach klasowych.','2026-11-13 00:45:09','2026-11-13 00:45:09'),(20,18,3,5,'Magiczna animacja studia Ghibli. Bogactwo wyobraźni Miyazakiego nie ma granic. Piękna i głęboka opowieść o dorastaniu.','2026-11-13 00:45:09','2026-11-13 00:45:09'),(21,19,2,5,'Pojedynek psychologiczny młodego perkusisty z bezwzględnym dyrygentem. Finałowe solo na perkusji wgniata w fotel! J.K. Simmons w roli życia.','2026-11-13 00:45:09','2026-11-13 00:45:09'),(22,20,4,5,'Poruszająca relacja zawodowego zabójcy i małej dziewczynki. Debiut Natalie Portman zachwyca do dziś, a Gary Oldman jako skrajnie zły gliniarz to klasa sama w sobie.','2026-11-13 00:45:09','2026-11-13 00:45:09');
INSERT INTO `users` VALUES (1,'admin','admin@bazafilmow.pl','$2y$10$gvz5D7B3Et.877.oSabUk.RNC0Ka1drhjBbdEyqf9GpFUM6DYVVGa','admin',0,'2026-11-13 00:45:09'),(2,'jan_kowalski','jan@example.com','$2y$10$.jASKLEUHlXQ.xKktZ3h6.YO6DWvgn6yiGvgFEy8ASVlJ5Lz6Mjci','user',0,'2026-11-13 00:45:09'),(3,'anna_nowak','anna@example.com','$2y$10$lfCatESx8472mGdmz1438.49B2ounzzAM3KD/32d1alUy98n8weaW','user',0,'2026-11-13 00:45:09'),(4,'piotr_wisniewski','piotr@example.com','$2y$10$CND0XmBqK/WxW4H6FOm8bOUb2jF6FwwFRZZ8SV.Ev9DNgZc3pZ5CS','user',0,'2026-11-13 00:45:09');
